                cnt = 0;
                dfs(i);
                long temp = (long) cnt * (cnt - 1) / 2;
                ans += temp * weight[i];
                allRoad -= temp;
            }
        }
        ans += (allRoad)*15;
        System.out.println(ans);
    }
    static int cnt;
    private static void dfs(int root){
        cnt++;
        visit[root] = true;
        for (Integer node : arr[root]){
            if(!visit[node] && weight[node] == weight[root]){
                dfs(node);
            }
        }
    }
}
